update country_flag_history set label_fr = 'République populaire ukrainienne', label_en = 'Ukrainian People''s Republic', notes_fr = 'Le bleu et jaune devient le drapeau de la république proclamée à Kyiv en 1917-1918, emportée par la guerre contre les bolcheviks.', notes_en = 'Blue and yellow became the flag of the republic proclaimed in Kyiv in 1917–1918, swept away by the war with the Bolsheviks.' where id = 2511 and iso_code = 'ua';
update country_flag_history set date_start = '1949-11-21', label_fr = 'RSS d''Ukraine (1949-1991)', label_en = 'Ukrainian SSR (1949–1991)', notes_fr = 'Comme les autres républiques, l''Ukraine soviétique reçoit en 1949 un drapeau rouge à bande bleue inférieure, avec faucille, marteau et étoile.', notes_en = 'Like the other republics, Soviet Ukraine received in 1949 a red flag with a lower blue band, with the hammer, sickle and star.', image_url = '/flags/history/ua-1949.svg' where id = 2284 and iso_code = 'ua';
update country_flag_history set label_fr = 'Ukraine indépendante (1991-1992)', label_en = 'Independent Ukraine (1991–1992)', notes_fr = 'Le bleu et jaune flotte sur le Parlement dès le 4 septembre 1991 ; il est officiellement adopté le 28 janvier 1992.', notes_en = 'Blue and yellow flew over Parliament from 4 September 1991; it was officially adopted on 28 January 1992.' where id = 2512 and iso_code = 'ua';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ua', '/flags/history/ua-1919.svg', '1919-03-14', '1929-05-15', 'RSS d''Ukraine (1919-1929)', 'Ukrainian SSR (1919–1929)', 'Premier drapeau de la république soviétique : rouge, avec les initiales de la république.', 'The Soviet republic''s first flag: red, with the republic''s initials.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ua', '/flags/history/ua-1929.svg', '1929-05-15', '1937-01-30', 'RSS d''Ukraine (1929-1937)', 'Ukrainian SSR (1929–1937)', 'Les initiales sont réécrites en ukrainien à l''époque de l''« ukrainisation ».', 'The initials were rewritten in Ukrainian during the "Ukrainisation" period.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ua', '/flags/history/ua-1937.svg', '1937-01-30', '1949-11-21', 'RSS d''Ukraine (1937-1949)', 'Ukrainian SSR (1937–1949)', 'La faucille et le marteau dorés s''ajoutent au-dessus des initiales « УРСР ».', 'The golden hammer and sickle were added above the initials "УРСР".');
